import AppKit
import Defaults
import GhosttyKit
import os

/// One terminal surface: an `NSView` that hosts a `ghostty_surface_t` (Metal-rendered by libghostty
/// given our `nsview`), drives a local PTY, and bridges macOS keyboard/IME/mouse into libghostty.
/// This is the libghostty replacement for SwiftTerm's `LocalProcessTerminalView`.
///
/// Ported from Muxy's `GhosttyTerminalNSView` (MIT) as inspiration, trimmed to Workroom's existing
/// feature set: no splits UI, search, progress, dynamic titles, or remote streaming. (File/image
/// drops are handled host-side — see the drag-and-drop extension below.)
///
/// Lifecycle (plan A1): the surface is created when the view enters a window and freed in
/// `tearDown()`/`deinit`; callbacks are nil'd and the C-string config pointers freed on teardown so
/// no in-flight libghostty callback can touch a dead view.
final class GhosttySurfaceView: NSView {
  private static let sessionLogger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "PersistentSession")

  /// The live surface, or nil before creation / after teardown. `nonisolated(unsafe)` because the
  /// runtime callbacks (via `ghostty_surface_userdata`) read it; all writes happen on the main thread.
  nonisolated(unsafe) private(set) var surface: ghostty_surface_t?

  /// Set once `tearDown()` runs — the view is dead and must NEVER re-spawn its surface. SwiftUI/AppKit
  /// can re-mount a still-referenced view after its tab closed (a `closeTab` teardown racing a pending
  /// view update); without this, `viewDidMoveToWindow` → `createSurface` would relaunch the command on
  /// the dead view, spawning an UNTRACKED duplicate the app can't stop — for a run command that's a
  /// phantom dev server orphaned on its port ("A server is already running" next start; issue #7).
  private(set) var isTornDown = false

  /// Unit-test seam for foreground-process recognition. Production always leaves this nil and asks
  /// libghostty for the PTY foreground process group.
  var foregroundProcessNameForTesting: String?

  var foregroundAgentBackend: AgentBackend? {
    if let foregroundProcessNameForTesting {
      return AgentProcessRecognition.backend(forProcessName: foregroundProcessNameForTesting)
    }
    guard let surface else { return nil }
    let pid = pid_t(ghostty_surface_foreground_pid(surface))
    return AgentProcessRecognition.backend(forPID: pid)
  }

  /// The cwd the surface spawned its shell in. `internal` (not `private`) so tests can assert it
  /// (e.g. the quick terminal at `~/`).
  let workingDirectory: String

  /// When non-nil/non-empty, the surface launches this command instead of a login shell, and keeps
  /// the pane open after it exits (`wait_after_command`). Used by the "run command" feature (issue
  /// #7); nil for every ordinary terminal. The host passes a shell-wrapped string (`$SHELL -lic …`).
  private let runCommand: String?

  /// Daemon session this surface attaches to. When set and the helper is available, `createSurface`
  /// launches `workroom-session attach` instead of a login shell.
  var persistentSessionID: UUID?

  /// Project / workroom / tab / title metadata sent on attach.
  var sessionMetadata: [(key: String, value: String)] = []

