private func createSurface() {
  guard canSpawnSurface, let app = GhosttyApp.shared.app else { return }
  guard let backingSize = backingPixelSize() else {
    pendingSurfaceCreation = true
    return
  }
  pendingSurfaceCreation = false

  var config = ghostty_surface_config_new()
  config.platform_tag = GHOSTTY_PLATFORM_MACOS
  config.platform = ghostty_platform_u(
    macos: ghostty_platform_macos_s(nsview: Unmanaged.passUnretained(self).toOpaque()))
  config.userdata = Unmanaged.passUnretained(self).toOpaque()
  config.scale_factor = Double(window?.backingScaleFactor ?? 2.0)
  config.context = GHOSTTY_SURFACE_CONTEXT_TAB  // Workroom: one surface per tab (no splits yet)

  // Spawn a login shell in the target directory. No explicit `command` → libghostty launches the
  // user's default shell as a login shell (matches Workroom's prior `startProcess(... -l)`).
  freeSurfaceCStrings()
  guard let cwd = strdup(workingDirectory) else { return }
  surfaceCStrings.append(cwd)
  config.working_directory = UnsafePointer(cwd)

  var envPairs: [(String, String)] = []
  if let terminfo = GhosttyApp.shared.terminfoDirectory {
    envPairs.append(("TERMINFO", terminfo))
  }

  let startedPersistent = applyPersistentSession(
    to: &config, environment: &envPairs)

  if !startedPersistent, let runCommand, !runCommand.isEmpty, let cmd = strdup(runCommand) {
    surfaceCStrings.append(cmd)
    config.command = UnsafePointer(cmd)
    config.wait_after_command = true
  }

  if !envPairs.isEmpty {
    let buffer = UnsafeMutablePointer<ghostty_env_var_s>.allocate(capacity: envPairs.count)
    for (index, pair) in envPairs.enumerated() {
      guard let key = strdup(pair.0), let value = strdup(pair.1) else { continue }
      surfaceCStrings.append(key)
      surfaceCStrings.append(value)
      buffer[index] = ghostty_env_var_s(key: UnsafePointer(key), value: UnsafePointer(value))
    }
    envVarsBuffer = buffer
    envVarCount = envPairs.count
    config.env_vars = buffer
    config.env_var_count = envPairs.count
  }

  surface = ghostty_surface_new(app, &config)
  guard let surface else {
    freeSurfaceCStrings()
    return
  }

  let scale = Double(window?.backingScaleFactor ?? 2.0)
  ghostty_surface_set_content_scale(surface, scale, scale)
  ghostty_surface_set_size(surface, backingSize.width, backingSize.height)
  applyColorScheme(isDark: Self.isCurrentAppearanceDark())
  if let screen = window?.screen ?? NSScreen.main,
    let displayID = screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? UInt32
  {
    ghostty_surface_set_display_id(surface, displayID)
  }
  applyOcclusionState()
  // Keep the overlay scrollbar and go-to-bottom button above the surface's Metal content.
  addSubview(scrollbarThumb, positioned: .above, relativeTo: nil)
  addSubview(goToBottomButton, positioned: .above, relativeTo: nil)
  layoutGoToBottomButton()
  // The surface may have been created AFTER this view already became first responder: a zero-bounds
  // attach defers `createSurface` to `setFrameSize`/`layout`, so `becomeFirstResponder` ran while
  // `surface == nil` and its `setSurfaceFocused(true)` no-oped (see `setSurfaceFocused`). Without
  // this the surface comes up blurred while the view holds first responder — keys reach `keyDown`
  // but libghostty drops them on an unfocused surface, and a click can't recover because
  // `makeFirstResponder` short-circuits on an already-first-responder view. Re-sync the flag now.
  adoptFocusIfFirstResponder()
}

/// Spawn the surface's PTY *without* waiting for window mount (issue #67, background run). Normally
/// `createSurface` fires from `viewDidMoveToWindow`, so a run tab that's started in the background and
/// never made active would never mount — and its command would never start (the toast would claim
/// "running" while nothing ran). `createSurface` only hard-requires positive bounds
/// (`backingPixelSize`); every window reference inside it is a soft fallback. So give the view a
/// non-zero frame and create the surface now; it re-sizes correctly when it later mounts into a real
/// pane. No-op if the surface already exists or this is a test view (`spawnsSurface == false`).
func ensureSurfaceCreated(initialSize: CGSize) {
  guard spawnsSurface, surface == nil else { return }
  if bounds.width <= 0 || bounds.height <= 0 {
    // Positive bounds are the one thing `createSurface` can't proceed without (it defers via
    // `pendingSurfaceCreation` otherwise). A sane initial size also gives the spawned command a
    // reasonable COLUMNS/LINES until the first on-window resize.
    let size =
      (initialSize.width > 0 && initialSize.height > 0)
      ? initialSize : CGSize(width: 800, height: 480)
    setFrameSize(size)
  }
  createSurface()
}

private func destroySurface() {
  if let surface { ghostty_surface_free(surface) }
  surface = nil
  lastSetFocus = nil  // a new surface starts unfocused — don't let a stale value skip the re-sync
  freeSurfaceCStrings()
}

/// Explicit teardown on close/delete (plan A1). Clears callbacks first so a late libghostty
/// callback resolving this view via `userdata` can't invoke a dangling closure, then frees.
func tearDown() {
  isTornDown = true  // dead view: block any later re-spawn (issue #7 phantom respawn)
  setHandCursor(false)
  onActivity = nil
  onOpenURL = nil
  onCmdClickFile = nil
  resolveCmdHoverFile = nil
  onFocused = nil
  onChildExited = nil
  onCloseRequested = nil
  progressActive = false
  progressTimeoutTimer?.invalidate()
  progressTimeoutTimer = nil
  stopAccessibilityPolling()
  if let occlusionObserver {
    NotificationCenter.default.removeObserver(occlusionObserver)
    self.occlusionObserver = nil
  }
  for observer in keyWindowObservers { NotificationCenter.default.removeObserver(observer) }
  keyWindowObservers = []
  destroySurface()
  removeFromSuperview()
}

deinit {
  progressTimeoutTimer?.invalidate()
  accessibilityPollTimer?.invalidate()
  if let occlusionObserver { NotificationCenter.default.removeObserver(occlusionObserver) }
  for observer in keyWindowObservers { NotificationCenter.default.removeObserver(observer) }
  if let surface { ghostty_surface_free(surface) }
  freeSurfaceCStrings()
}

private func freeSurfaceCStrings() {
  for ptr in surfaceCStrings { free(ptr) }
  surfaceCStrings.removeAll()
  envVarsBuffer?.deinitialize(count: envVarCount)
  envVarsBuffer?.deallocate()
  envVarsBuffer = nil
  envVarCount = 0
}

/// Configure libghostty to spawn `workroom-session attach` for a background session.
@discardableResult
private func applyPersistentSession(
  to config: inout ghostty_surface_config_s,
  environment: inout [(String, String)]
) -> Bool {
  // No session was requested for this pane — not a failure, nothing to log.
  guard let persistentSessionID else { return false }
  guard
    PersistentSessionService.shared.isAvailable,
    let attach = PersistentSessionService.shared.attachCommand(),
    let attachPointer = strdup(attach)
  else {
    // A pane that expected a persisted session fell back to a plain login shell. Whatever the
    // daemon-side session was doing is now orphaned/unreachable from this pane — worth a log
    // line since the resulting terminal otherwise looks identical to a normal fresh shell.
    Self.sessionLogger.error(
      """
      persistent session \(persistentSessionID.uuidString, privacy: .public) unavailable \
      (helper isAvailable=\(PersistentSessionService.shared.isAvailable, privacy: .public)); \
      falling back to a plain shell
      """)
    return false
  }
  surfaceCStrings.append(attachPointer)
  config.command = UnsafePointer(attachPointer)
  config.wait_after_command = false
  environment.append(
    contentsOf: PersistentSessionService.shared.launchEnvironment(
      sessionID: persistentSessionID,
      workingDirectory: workingDirectory,
      metadata: sessionMetadata))
  return true
}

func reattachPersistentSession() {
  guard persistentSessionID != nil, !isTornDown else { return }
  destroySurface()
  if bounds.width <= 0 || bounds.height <= 0 {
    setFrameSize(CGSize(width: 800, height: 480))
  }
  createSurface()
}

// MARK: Geometry / render sizing

private func backingPixelSize() -> (width: UInt32, height: UInt32)? {
  let size = convertToBacking(bounds).size
  let w = Int(floor(size.width))
  let h = Int(floor(size.height))
  guard w > 0, h > 0 else { return nil }
  return (UInt32(w), UInt32(h))
}

private func updateMetalLayerSize() {
  guard let surface, let window else { return }
  layer?.contentsScale = window.backingScaleFactor
  let scale = Double(window.backingScaleFactor)
  ghostty_surface_set_content_scale(surface, scale, scale)
  if let screen = window.screen,
    let displayID = screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? UInt32
  {
    ghostty_surface_set_display_id(surface, displayID)
  }
  if let backingSize = backingPixelSize() {
    ghostty_surface_set_size(surface, backingSize.width, backingSize.height)
  }
}

override func viewDidMoveToWindow() {
  super.viewDidMoveToWindow()
  if let occlusionObserver {
    NotificationCenter.default.removeObserver(occlusionObserver)
    self.occlusionObserver = nil
  }
  for observer in keyWindowObservers { NotificationCenter.default.removeObserver(observer) }
  keyWindowObservers = []
  guard let window else {
    // Detached from any window → stop rendering. `updateWindowVisibility` defaults to "visible"
    // when window is nil, so set it explicitly here rather than leaving the last (stale) value.
    isWindowVisible = false
    applyOcclusionState()
    stopAccessibilityPolling()
    return
  }
  if surface == nil { createSurface() }
  startAccessibilityPolling()
  occlusionObserver = NotificationCenter.default.addObserver(

