259	  private func handle(frame: SessionFrame, connection: SessionConnection) {
260	    switch frame.kind {
261	    case .attach:
262	      handleAttach(payload: frame.payload, connection: connection)
263	    case .input:
264	      guard let identifier = connection.attachedSession, let session = sessions[identifier] else {
265	        return
266	      }
267	      session.appendInput(frame.payload, limit: Self.sessionInputLimit)
268	      session.flushInput()
269	    case .resize:
270	      guard let identifier = connection.attachedSession,
271	        let session = sessions[identifier],
272	        let size = try? SessionResizePayload.decode(frame.payload)
273	      else { return }
274	      guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
275	      SessionPTY.resize(
276	        masterDescriptor: session.masterDescriptor, columns: size.columns, rows: size.rows)
277	    case .list:
278	      connection.enqueue(
279	        SessionFrame(
280	          kind: .sessions,
281	          payload: SessionDescriptor.encodeList(sessions.values.map(\.descriptor))))
282	    case .info:
283	      guard let identifier = try? SessionIdentifierPayload.decode(frame.payload) else { return }
284	      let matches = sessions[identifier].map { [$0.descriptor] } ?? []
285	      connection.enqueue(
286	        SessionFrame(kind: .sessions, payload: SessionDescriptor.encodeList(matches)))
287	    case .kill:
288	      let stopped: Bool
289	      if let identifier = try? SessionIdentifierPayload.decode(frame.payload),
290	        let session = sessions[identifier]
291	      {
292	        stopped = endSession(session, status: 0, force: true)
293	      } else {
294	        stopped = true
295	      }
296	      enqueueStopResult(stopped, connection: connection)
297	    case .killAll:
298	      enqueueStopResult(endSessions(Array(sessions.values), status: 0), connection: connection)
299	    case .attached, .output, .exited, .failure, .sessions, .acknowledged:
300	      break
301	    }
302	  }
303	
304	  private func handleAttach(payload: [UInt8], connection: SessionConnection) {
305	    guard let request = try? SessionAttachRequest.decode(payload) else {
306	      connection.enqueue(
307	        SessionFrame(
308	          kind: .failure, payload: SessionTextPayload.encode("malformed attach request")))
309	      connection.closesAfterFlush = true
310	      return
311	    }
312	    guard request.version == SessionProtocolVersion.current else {
313	      connection.enqueue(
314	        SessionFrame(
315	          kind: .failure,
316	          payload: SessionTextPayload.encode(
317	            "this background session is owned by a different version of Workroom; stop it to start a new one"
318	          )))
319	      connection.closesAfterFlush = true
320	      return
321	    }
322	    guard connection.attachedSession == nil else { return }
323	
324	    if let session = sessions[request.identifier] {
325	      attach(session: session, request: request, connection: connection)
326	      return
327	    }
328	    create(request: request, connection: connection)
329	  }
330	
331	  private func attach(
332	    session: PTYSession, request: SessionAttachRequest, connection: SessionConnection
333	  ) {
334	    if let previous = session.clientDescriptor, previous != connection.descriptor {
335	      connections[previous]?.attachedSession = nil
336	      markForClose(previous)
337	    }
338	    session.clientDescriptor = connection.descriptor
339	    session.metadata = request.metadata
340	    connection.attachedSession = session.identifier
341	
342	    if SessionWindowSizePolicy.isUsable(columns: request.columns, rows: request.rows) {
343	      SessionPTY.resize(
344	        masterDescriptor: session.masterDescriptor,
345	        columns: request.columns,
346	        rows: request.rows)
347	    }
348	    connection.enqueue(
349	      SessionFrame(
350	        kind: .attached,
351	        payload: SessionAttachAccepted(
352	          created: false,
353	          shellProcessID: session.processID,
354	          ttyDevice: session.ttyDevice
355	        ).encoded()))
356	    enqueueReplay(session: session, connection: connection)
357	    // Query the CURRENT size fresh rather than trusting `request.columns/rows` — those may have
358	    // been rejected as unusable above (a transient tiny size from a not-yet-laid-out surface), in
359	    // which case the redraw must still bump from/to whatever size the session's pty actually has.
360	    //
361	    // The bump happens now (cheap, a single ioctl); the resize-back-and-signal is DEFERRED to the
362	    // poll loop (`processExpiredRedraws`), not done here inline with a blocking sleep — this daemon
363	    // is single-threaded and serves every session across every open project, so sleeping here would
364	    // freeze all of them for the duration, worst case stacking to N × the settle window when many
365	    // persisted tabs reattach at once on relaunch.
366	    if let current = SessionPTY.windowSize(descriptor: session.masterDescriptor) {
367	      SessionPTY.resize(
368	        masterDescriptor: session.masterDescriptor, columns: current.columns,
369	        rows: SessionPTY.bumpedRowCount(current.rows))
370	      pendingRedraws[session.identifier] = PendingRedraw(
371	        deadline: SessionClock.monotonicSeconds() + Self.redrawSettleSeconds,
372	        columns: current.columns, rows: current.rows)
373	    }
374	  }
375	
376	  private func enqueueReplay(session: PTYSession, connection: SessionConnection) {
377	    let bytes = session.replay.replayBytes
378	    guard !bytes.isEmpty else { return }
379	    var index = 0
380	    while index < bytes.count {
381	      let end = min(index + Self.replayChunkSize, bytes.count)
382	      connection.enqueue(SessionFrame(kind: .output, payload: Array(bytes[index..<end])))
383	      index = end
384	    }
385	  }
386	
387	  private func create(request: SessionAttachRequest, connection: SessionConnection) {
388	    guard sessions.count < Self.maximumSessions else {
389	      connection.enqueue(
390	        SessionFrame(
391	          kind: .failure,
392	          payload: SessionTextPayload.encode("too many background sessions")))
393	      connection.closesAfterFlush = true
394	      return
395	    }
396	    let invocation = SessionShellIntegration.invocation(
397	      command: request.command,
398	      shell: request.shell,
399	      resourcesDirectory: request.resourcesDirectory,
400	      environment: request.environment)
401	    let size = SessionWindowSizePolicy.createSize(columns: request.columns, rows: request.rows)
402	    guard
403	      let process = SessionPTY.spawn(
404	        invocation: invocation,
405	        workingDirectory: request.workingDirectory,
406	        columns: size.columns,
407	        rows: size.rows)
408	    else {
409	      connection.enqueue(
410	        SessionFrame(
411	          kind: .failure, payload: SessionTextPayload.encode("failed to start the session")))
412	      connection.closesAfterFlush = true
413	      return
414	    }
415	
416	    let session = PTYSession(
417	      identifier: request.identifier,
418	      process: process,
419	      workingDirectory: request.workingDirectory,
420	      replayCapacity: Self.replayCapacity)
421	    session.clientDescriptor = connection.descriptor
422	    session.metadata = request.metadata
423	    sessions[request.identifier] = session
424	    sessionsByMaster[process.masterDescriptor] = request.identifier
