4	enum AgentQuotaWindowKind: Equatable, Sendable {
5	  case fiveHour
6	  case weekly
7	  case duration(minutes: Int)
8	
9	  var compactLabel: String {
10	    switch self {
11	    case .fiveHour: return "5h"
12	    case .weekly: return "wk"
13	    case .duration(let minutes):
