1	/// Ring buffer of recent PTY output, replayed to a client that reattaches.
2	///
3	/// Drops contents while the alternate screen is active (full-screen programs get SIGWINCH
4	/// instead). On wrap, leading/trailing escape and UTF-8 fragments are trimmed so a mid-sequence
5	/// cut does not corrupt the terminal.
6	///
7	/// Inspired by Muxy's SessionReplayBuffer (MIT).
8	public struct SessionReplayBuffer: Sendable {
9	  private static let alternateScreenEnterSequences: [[UInt8]] = [
10	    [0x1B, 0x5B, 0x3F, 0x34, 0x37, 0x68],
11	    [0x1B, 0x5B, 0x3F, 0x31, 0x30, 0x34, 0x37, 0x68],
12	    [0x1B, 0x5B, 0x3F, 0x31, 0x30, 0x34, 0x39, 0x68],
13	  ]
14	
15	  private static let alternateScreenLeaveSequences: [[UInt8]] = [
16	    [0x1B, 0x5B, 0x3F, 0x34, 0x37, 0x6C],
17	    [0x1B, 0x5B, 0x3F, 0x31, 0x30, 0x34, 0x37, 0x6C],
18	    [0x1B, 0x5B, 0x3F, 0x31, 0x30, 0x34, 0x39, 0x6C],
19	  ]
20	
21	  private static let screenControlTailLength = max(
22	    alternateScreenEnterSequences.map(\.count).max() ?? 0,
23	    alternateScreenLeaveSequences.map(\.count).max() ?? 0)
24	
25	  public let capacity: Int
26	
27	  private var storage: [UInt8]
28	  private var start = 0
29	  private var count = 0
30	  private var hasDiscardedBytes = false
31	  private var alternateScreenActive = false
32	  private var screenControlTail: [UInt8] = []
33	
34	  public init(capacity: Int) {
35	    self.capacity = max(capacity, 0)
36	    storage = [UInt8](repeating: 0, count: self.capacity)
37	  }
38	
39	  public var isEmpty: Bool { count == 0 }
40	  public var byteCount: Int { count }
41	  public var isAlternateScreenActive: Bool { alternateScreenActive }
42	
43	  public mutating func append(_ bytes: [UInt8]) {
44	    bytes.withUnsafeBufferPointer { append($0) }
45	  }
46	
47	  public mutating func append(_ bytes: UnsafeBufferPointer<UInt8>) {
48	    guard capacity > 0, !bytes.isEmpty else { return }
49	    appendForReplay(Array(bytes))
50	  }
51	
52	  public var replayBytes: [UInt8] {
53	    guard !alternateScreenActive else { return [] }
54	    var output = bytes
55	    var needsLeadingFragmentCleanup = false
56	    if hasDiscardedBytes {
